import { BooleanColumn, Table, StringColumn, GenericColumn, TranslatedTextColumn, UserRolesColumn } from '../../db'

export const sys_properties = Table({
    name: 'sys_properties',
    schema: {
        choices: StringColumn({
            mandatory: false,
            label: 'Choices',
            read_only: false,
            active: true,
            maxLength: 512,
            dropdown: 'none',
        }),
        description: TranslatedTextColumn({ mandatory: false, label: 'Description', read_only: false, active: true }),
        ignore_cache: BooleanColumn({
            mandatory: false,
            label: 'Ignore cache',
            read_only: false,
            active: true,
            default: false,
        }),
        is_private: BooleanColumn({
            mandatory: false,
            label: 'Private',
            read_only: false,
            active: true,
            default: false,
        }),
        name: StringColumn({
            mandatory: false,
            label: 'Name',
            read_only: false,
            active: true,
            maxLength: 100,
            dropdown: 'none',
        }),
        read_roles: UserRolesColumn({ mandatory: false, label: 'Read roles', read_only: false, active: true }),
        suffix: StringColumn({
            mandatory: false,
            label: 'Suffix',
            read_only: false,
            active: true,
            maxLength: 100,
            dropdown: 'none',
        }),
        sys_id: GenericColumn({
            mandatory: false,
            label: 'Sys ID',
            read_only: false,
            active: true,
            column_type: 'GUID',
        }),
        type: StringColumn({
            mandatory: false,
            label: 'Type',
            read_only: false,
            active: true,
            default: 'string',
            maxLength: 40,
            dropdown: 'dropdown_with_none',
            choices: {
                boolean: { label: 'true | false', inactive: false, language: 'en' },
                password2: { label: 'password2', inactive: false, language: 'en' },
                date_format: { label: 'date format', inactive: false, language: 'en' },
                integer: { label: 'integer', inactive: false, language: 'en' },
                choicelist: { label: 'choice list', inactive: false, language: 'en' },
                time_format: { label: 'time format', inactive: false, language: 'en' },
                image: { label: 'image', inactive: false, language: 'en' },
                color: { label: 'color', inactive: false, language: 'en' },
                uploaded_image: { label: 'uploaded image', inactive: false, language: 'en' },
                password: { label: 'password', inactive: false, language: 'en' },
                timezone: { label: 'timezone', inactive: false, language: 'en' },
                short_string: { label: 'short string (40 characters or less)', inactive: false, language: 'en' },
                string: { label: 'string', inactive: false, language: 'en' },
            },
        }),
        value: StringColumn({
            mandatory: false,
            label: 'Value',
            read_only: false,
            active: true,
            maxLength: 4000,
            dropdown: 'none',
        }),
        write_roles: UserRolesColumn({ mandatory: false, label: 'Write roles', read_only: false, active: true }),
    },
})

export const PropertyTypeChoices = sys_properties['schema']['type']['choices']

export type PropertyType = keyof typeof PropertyTypeChoices
